-- =========================================================
--  호텔 예약 사이트 DB 스크립트
--  HeidiSQL에서 이 파일을 열고 전체 실행(F9)하면 됩니다.
--  접속 정보: src/main/java/pool.jocl -> jdbc:mysql://localhost:3306/hotel (root / 12345)
--  다시 실행하면 이 프로젝트 테이블만 지우고 처음부터 새로 만듭니다.
-- =========================================================

-- 이 프로젝트 전용 hotel 데이터베이스 (없으면 새로 만듦)
CREATE DATABASE IF NOT EXISTS hotel DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci;
USE hotel;

DROP TABLE IF EXISTS guest;
DROP TABLE IF EXISTS member_coupon;
DROP TABLE IF EXISTS translation;
DROP TABLE IF EXISTS faq;
DROP TABLE IF EXISTS qna;
DROP TABLE IF EXISTS review;
DROP TABLE IF EXISTS reservation;
DROP TABLE IF EXISTS coupon;
DROP TABLE IF EXISTS room;
DROP TABLE IF EXISTS member;

-- 회원 : userId가 'admin'이면 관리자, 나머지는 일반 이용자
CREATE TABLE member (
	userId        VARCHAR(50)  NOT NULL,
	password      VARCHAR(50)  NOT NULL,
	name          VARCHAR(50)  NOT NULL,
	phone         VARCHAR(20),
	email         VARCHAR(100),
	registerTime  DATETIME     NOT NULL,
	PRIMARY KEY (userId)
);

-- 객실
CREATE TABLE room (
	roomId        INT          NOT NULL AUTO_INCREMENT,
	roomType      VARCHAR(50)  NOT NULL,          -- 객실 유형 (스탠다드, 디럭스 ...)
	roomNo        VARCHAR(10)  NOT NULL,          -- 호실 (101호 ...)
	roomSize      INT          NOT NULL DEFAULT 0,-- 객실 크기 (평)
	price         INT          NOT NULL,          -- 1박 정가
	discountRate  INT          NOT NULL DEFAULT 0,-- 객실 할인율(%)
	capacity      INT          NOT NULL,          -- 최대 인원
	baseGuests    INT          NOT NULL DEFAULT 2,-- 기준 인원 (이 인원까지는 기본 요금)
	extraPrice    INT          NOT NULL DEFAULT 0,-- 기준 인원을 넘는 1명당 1박 추가 요금
	bedCount      INT          NOT NULL DEFAULT 1,-- 침대 수
	breakfast     TINYINT      NOT NULL DEFAULT 0,-- 조식 포함 1 / 미포함 0
	pet           TINYINT      NOT NULL DEFAULT 0,-- 반려동물 동반 1 / 불가 0
	viewType      VARCHAR(20)  NOT NULL DEFAULT '시티뷰',-- 전망 (오션뷰 / 시티뷰 / 파크뷰)
	amenities     VARCHAR(200) NOT NULL DEFAULT '',-- 편의시설 (쉼표로 구분)
	description   TEXT,
	photo         LONGBLOB,                       -- 사진 파일 내용 (이미지 자체를 DB에 저장)
	photoType     VARCHAR(50),                    -- 사진 종류 (image/jpeg, image/png ...)
	-- 아래 3개는 수업 movie.freq 처럼 예약/리뷰가 생길 때마다 update 로 갱신하는 값
	avgRating     DOUBLE       NOT NULL DEFAULT 0,-- 평균 평점
	reviewCount   INT          NOT NULL DEFAULT 0,-- 리뷰 수
	resCount      INT          NOT NULL DEFAULT 0,-- 예약 수 (인기순 정렬용)
	PRIMARY KEY (roomId)
);

-- 쿠폰 (쿠폰 종류) : 사용 기간(startDate ~ endDate) 안에서만 쓸 수 있음
--   회원은 쿠폰 번호를 입력하지 않고, 쿠폰함(member_coupon)에 받은 쿠폰을 결제 화면에서 골라 쓴다
CREATE TABLE coupon (
	couponCode    VARCHAR(30)  NOT NULL,
	couponName    VARCHAR(100) NOT NULL,
	discountRate  INT          NOT NULL,          -- 할인율(%)
	startDate     DATE         NOT NULL,
	endDate       DATE         NOT NULL,
	issueType     VARCHAR(10)  NOT NULL DEFAULT '다운로드',-- 받는 방법 : 가입축하 / 다운로드 / 관리자지급
	PRIMARY KEY (couponCode)
);

-- 회원이 등록해 둔 투숙객 : 예약할 때 결제 화면에서 골라서 이름·연락처를 바로 채움
CREATE TABLE guest (
	guestId       INT          NOT NULL AUTO_INCREMENT,
	userId        VARCHAR(50)  NOT NULL,          -- 등록한 회원
	name          VARCHAR(50)  NOT NULL,
	phone         VARCHAR(20)  NOT NULL,
	relation      VARCHAR(10)  NOT NULL,          -- 가족 / 배우자 / 친구 / 동료 / 기타
	PRIMARY KEY (guestId)
);

-- 회원 쿠폰함 : 회원이 받은 디지털 쿠폰 한 장 = 한 줄 (같은 쿠폰은 한 사람에 한 장)
--   쿠폰 이름, 할인율, 기간은 받을 때 복사해 둔다 → join 없이 쿠폰함을 바로 보여줌
CREATE TABLE member_coupon (
	mcId          INT          NOT NULL AUTO_INCREMENT,
	userId        VARCHAR(50)  NOT NULL,
	couponCode    VARCHAR(30)  NOT NULL,
	couponName    VARCHAR(100) NOT NULL,
	discountRate  INT          NOT NULL,
	startDate     DATE         NOT NULL,
	endDate       DATE         NOT NULL,
	used          TINYINT      NOT NULL DEFAULT 0,-- 사용했으면 1 (예약을 취소하면 다시 0)
	usedResId     INT          NOT NULL DEFAULT 0,-- 어느 예약에 썼는지
	issueDate     DATETIME     NOT NULL,
	PRIMARY KEY (mcId)
);

-- 예약 : status 는 '예약완료' 또는 '취소'
CREATE TABLE reservation (
	resId         INT          NOT NULL AUTO_INCREMENT,
	userId        VARCHAR(50)  NOT NULL,
	roomId        INT          NOT NULL,
	roomType      VARCHAR(50)  NOT NULL,          -- 예약할 때의 객실 이름을 같이 저장 (join 없이 바로 보여주려고)
	roomNo        VARCHAR(10)  NOT NULL,
	checkIn       DATE         NOT NULL,
	checkOut      DATE         NOT NULL,
	guests        INT          NOT NULL,
	totalPrice    INT          NOT NULL,
	couponCode    VARCHAR(30),
	payMethod     VARCHAR(20)  NOT NULL,          -- 현장결제 / 계좌이체 / 카드결제
	payDetail     VARCHAR(100),                   -- 결제 상세 (카드사 / 할부, 입금자명 ...) 예약 확인서에 표시
	requestNote   VARCHAR(500),                   -- 고객 요청사항 (없으면 NULL)
	guestName     VARCHAR(50),                    -- 실제 투숙객 이름 (예약자와 다를 수 있음)
	guestPhone    VARCHAR(20),                    -- 투숙객 연락처
	status        VARCHAR(10)  NOT NULL DEFAULT '예약완료',
	reviewed      TINYINT      NOT NULL DEFAULT 0,-- 리뷰를 썼으면 1
	resDate       DATETIME     NOT NULL,
	PRIMARY KEY (resId)
);

-- 리뷰 : 예약 1건당 리뷰 1개
CREATE TABLE review (
	reviewId      INT          NOT NULL AUTO_INCREMENT,
	resId         INT          NOT NULL,
	userId        VARCHAR(50)  NOT NULL,
	roomId        INT          NOT NULL,
	roomType      VARCHAR(50)  NOT NULL,          -- 어느 객실 리뷰인지 바로 보여주려고 같이 저장
	rating        INT          NOT NULL,          -- 1 ~ 5
	content       TEXT         NOT NULL,
	regDate       DATETIME     NOT NULL,
	PRIMARY KEY (reviewId)
);

-- 1:1 문의 : answer 가 NULL 이면 답변 대기
CREATE TABLE qna (
	qnaId         INT          NOT NULL AUTO_INCREMENT,
	userId        VARCHAR(50)  NOT NULL,
	title         VARCHAR(200) NOT NULL,
	content       TEXT         NOT NULL,
	answer        TEXT,
	regDate       DATETIME     NOT NULL,
	answerDate    DATETIME,
	PRIMARY KEY (qnaId)
);

-- 자주 묻는 질문 : 이용자 FAQ 화면과 AI 챗봇 답변 근거로 사용
CREATE TABLE faq (
	faqId         INT          NOT NULL AUTO_INCREMENT,
	category      VARCHAR(20)  NOT NULL,          -- 예약·결제 / 객실 / 시설·서비스 / 회원
	question      VARCHAR(200) NOT NULL,
	answer        TEXT         NOT NULL,
	PRIMARY KEY (faqId)
);

-- 영어 번역 캐시 : 한 번 AI(Ollama)로 번역한 문장을 저장해 두고 다시 씀
CREATE TABLE translation (
	ko            VARCHAR(700) NOT NULL,          -- 화면의 한글 문장
	en            TEXT         NOT NULL,          -- 영어 번역
	PRIMARY KEY (ko)
);

